import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  const root = new Group();

  // Plane geometry preserving aspect ratio of the source image (512x320 = 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new Mesh(geometry, material);
  plane.renderOrder = 0;
  root.add(plane);

  // Load texture asynchronously but apply synchronously when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text content handling
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: config.visual?.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // No cinematic primitives to apply for this node

  // UserData for handlers and cleanup
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if any
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines (none created here, but safe guard)
    if (gsap.globalTimeline) {
      gsap.globalTimeline.clear();
    }
  };

  return root;
}
